#include <algorithm> #include <iostream> using namespace std;
long long mod=1000000007;
int fact(int n) {
    int res=1;
    for(int i=2;i<=n;i ++)res=res*i;
    return res ;
}
int nCr(int n,int r) {
    return fact(n)/(fact(r)* fact(n-r)) ;
}
long long powmod(long long a,long long n) {
    if(! n)return 1;
    long long pt=powmod(a,n/2);
    pt =(pt*pt)% mod;
    if(n%2)return(pt*a)% mod;
    else return pt ;
}
long long CountSubset(int*arr,int n) {
    long long ans=powmod(2,n-1);
    sort(arr,arr+n);
    for(int i=0;i<n;++ i) {
        int j=i+1;
        while(j<n&&arr[j]== arr[i]) {
            int r=n-1-j;
            int l=i;
            ans =(ans+nCr(l+r,l))%mod;
            j++;
        }
    }
    return ans;
}

#include <cstdlib> #include <iostream> using namespace std;
char findKthChar(string s,int k) {
    int len=s.length();
    int i=0;
    int total_len=0;
    while(i<len) {
        if(isalpha(s[i])) {
            total_len ++;
            if(total_len==k)return s[i];
            i++;
        }
        else {
            int n=0;
            while(i<len&&! isalpha(s[i])) {
                n=n*10 +(s[i]- '0');
                i++;
            }
            int next_total_len=total_len*n;
            if(k<=next_total_len) {
                int pos=k%total_len;
                if(! pos) {
                    pos=total_len ;
                }
                return findKthChar(s,pos);
            }
            else {
                total_len=next_total_len ;
            }
        }
    }
    return -1;
}

