#include <iostream> #include <stdlib.h> using namespace std;
void printBinStr(int*str,int len) {
    for(int i=0;i<len;i ++) {
        cout<<str[i];
    }
    cout<<endl ;
}
void generateBinStr(int*str,int len,int currlen,int occur,int nextbit) {
    if(currlen==len) {
        if(occur==2&&nextbit==0)printBinStr(str,len);
        return ;
    }
    if(currlen==0) {
        str[0]= nextbit;
        generateBinStr(str,len,currlen+1,occur,0);
        generateBinStr(str,len,currlen+1,occur,1);
    }
    else {
        if(occur<2) {
            str[currlen]= nextbit;
            if(str[currlen-1]== 0&&nextbit==1) {
                occur+=1 ;
            }
            generateBinStr(str,len,currlen+1,occur,0);
            generateBinStr(str,len,currlen+1,occur,1);
        }
        else {
            if(str[currlen-1]== 0&&nextbit==1) {
                return ;
            }
            else {
                str[currlen]= nextbit;
                generateBinStr(str,len,currlen+1,occur,0);
                generateBinStr(str,len,currlen+1,occur,1);
            }
        }
    }
}

#include <iostream> #include <string> using namespace std;
bool checkPrime(string number) {
    int num=stoi(number);
    for(int i=2;i*i<=num;i ++)if(( num%i)== 0)return false;
    return true ;
}
int splitIntoPrimes(string number) {
    if(number.length()==0)return 0;
    if(number.length()<=6 and checkPrime(number)) return 1;
    else {
        int numLen=number.length();
        int ans=1000000;
        for(int i=1;i<=6&&i<=numLen;i ++) {
            if(checkPrime(number.substr(0,i))) {
                int val=splitIntoPrimes(number.substr(i));
                if(val!=-1) {
                    ans=min(ans,1+val);
                }
            }
        }
        if(ans==1000000)return -1;
        return ans ;
    }
}

