bool isPrime(int x) {
    int sqroot=sqrt(x);
    bool flag=true;
    if(x==1)return false;
    for(int i=2;i<=sqroot;i ++)if(x%i==0)return false;
    return true ;
}
void display() {
    int length=set.size();
    for(int i=0;i<length;i ++)cout<<set[i]<< " ? ";
    cout<<" STR" ;
}
void primeSum(int total,int N,int S,int index) {
    if(total==S&&set.size()==N) {
        display();
        return ;
    }
    if(total>S||index==prime.size())return;
    set.push_back(prime[index]);
    primeSum(total+prime[index], N,S,index+1);
    set.pop_back();
    primeSum(total,N,S,index+1);
}
void allPrime(int N,int S,int P) {
    for(int i=P+1;i<=S;i ++) {
        if(isPrime(i)) prime.push_back(i);
    }
    if(prime.size()<N)return;
    primeSum(0,N,S,0);
}

#include <iostream> #include <vector> using namespace std;
void GetAllValidIpAddress(vector<string >&result,string givenString,int index,int count,string ipAddress) {
    if(givenString.size()==index&&count==4) {
        ipAddress.pop_back();
        result.push_back(ipAddress);
        return ;
    }
    if(givenString.size()<index+1)return;
    ipAddress=ipAddress+givenString.substr(index,1)+ '.';
    GetAllValidIpAddress(result,givenString,index+1,count+1,ipAddress);
    ipAddress.erase(ipAddress.end()-2,ipAddress.end());
    if(givenString.size()<index+2 givenString[index]== '0')return;
    ipAddress=ipAddress+givenString.substr(index,2)+ '.';
    GetAllValidIpAddress(result,givenString,index+2,count+1,ipAddress);
    ipAddress.erase(ipAddress.end()-3,ipAddress.end());
    if(givenString.size()<index+3||stoi(givenString.substr(index,3))>255)return;
    ipAddress+=givenString.substr(index,3)+ '.';
    GetAllValidIpAddress(result,givenString,index+3,count+1,ipAddress);
    ipAddress.erase(ipAddress.end()-4,ipAddress.end());
}

