int MinOfCubed(int k) {
    if(k<8)return k;
    int res=k;
    for(int i=1;i<=k;i ++) {
        if(( i*i*i)> k)return res;
        res=min(res,MinOfCubed(k -(i*i*i))+1);
    }
    return res;
}

