    int n=y/g;
    int res=n;
    for(int i=2;i*i<=n;i ++) {
        if(n%i==0) {
            res -=(res/i);
            while(n%i==0)n/=i ;
        }
    }
    if(n!=1)res -=(res/n);
    return res;
}

