bool dfs(bool graph[101][101], int curr, int V, int m, vector<int> &colors)
{
  if (curr == V)
    return true;

  for (int c = 1; c <= m; ++c)
  {
    int flag = 0;
    colors[curr] = c;

    for (int i = 0; i < V; ++i)
    {
      if (graph[curr][i] && colors[i] == c)
      {
        flag = 1;
        break;
      }
    }

    if (!flag)
    {
      if (dfs(graph, curr + 1, V, m, colors))
        return true;
    }

    colors[curr] = 0;
  }

  return false;
}

bool dfs(const string& pattern, int index, string& res, int state){

        if(index == pattern.size()) return true;

        if(pattern[index] == 'I'){
            for(int d = res[index] - '0' + 1; d <= 9; d ++){
                if((state & (1 << d)) == 0){
                    res[index + 1] = (char)('0' + d);
                    if(dfs(pattern, index + 1, res, state | (1 << d))) return true;
                }
            }
        }
        else{
            for(int d = 1; d < res[index] - '0'; d ++){
                if((state & (1 << d)) == 0){
                    res[index + 1] = (char)('0' + d);
                    if(dfs(pattern, index + 1, res, state | (1 << d))) return true;
                }
            }
        }
        return false;
    }

bool dfs(const string& s, int index, const vector<string>& wordDict,
             vector<int>& dp){

        if(index == s.size()) return true;
        if(dp[index] != -1) return dp[index];

        int left = s.size() - index;
        for(const string& word: wordDict)
            if(left >= word.size() && s.substr(index, word.size()) == word &&
               dfs(s, index + word.size(), wordDict, dp)) return dp[index] = true;
        return dp[index] = false;
    }

bool dfs(const vector<int>& nums, int index, vector<int>& cur){

        if(index == nums.size()){
            for(int e: cur)
                if(e)
                    return false;
            return true;
        }

        for(int i = 0; i < cur.size() ; i ++)
            if(cur[i] >= nums[index]){
                cur[i] -= nums[index];
                if(dfs(nums, index + 1, cur))
                    return true;
                cur[i] += nums[index];
            }
        return false;
    }

bool dfs(int a[], int j, int k, int n, int vis[], int t, int c)
{
  if (c > t)
    return false;
  if (j == k)
    return true;
  if (c == t)
  {
    return dfs(a, j + 1, k, n, vis, t, 0);
  }

  for (int l = 0; l < n; ++l)
  {
    if (!vis[l])
    {
      vis[l] = 1;
      if (dfs(a, j, k, n, vis, t, c + a[l]))
        return true;
      vis[l] = 0;
    }
  }
  return false;
}

bool dfs(int curr, vector<int> adj[], vector<int> &rec, vector<int> &vis)
  {
    if (rec[curr])
      return true;

    rec[curr] = 1;

    for (auto &i : adj[curr])
    {
      if (!vis[i] && dfs(i, adj, rec, vis))
        return true;
    }

    vis[curr] = 1;
    rec[curr] = 0;
    return false;
  }

bool dfs(int curr, vector<int> adj[], vector<int> &vis, int par)
  {
