    {
      if (i != par)
      {
        if (vis[i])
          return true;
        vis[i] = 1;
        if (dfs(i, adj, vis, curr))
          return true;
      }
    }
    return false;
  }

bool dfs(int x, vector<int>& dp, bool isAlice){

        if(x == 1) return isAlice ? false : true;

        if(dp[x] != -1) return dp[x];

        if(isAlice){
            for(int i = 1; i * i <= x; i ++)
                if(x % i == 0 && dfs(x - i, dp, false))
                    return dp[x] = true;
            return dp[x] = false;
        }
        else{
            for(int i = 1; i * i <= x; i ++)
                if(x % i == 0 && !dfs(x - i, dp, true))
                    return dp[x] = false;
            return dp[x] = true;
        }
    }

bool dfs(string& s, int index, int& cnt, int n, int k){

