bool isScramble(string s1, string s2) {

        if(s1.size() != s2.size())
            return false;

        if(s1 == s2)
            return true;

        unordered_map<char, int> freq;
        for(char c: s1)
            freq[c] += 1;
        for(char c: s2)
            if(freq.find(c) == freq.end())
                return false;
            else{
                freq[c] -= 1;
                if(freq[c] == 0)
                    freq.erase(c);
            }


        for(int i = 1 ; i <= s1.size() - 1 ; i ++){
            if(isScramble(s1.substr(0, i), s2.substr(0, i))
               && isScramble(s1.substr(i), s2.substr(i)))
                return true;
            if(isScramble(s1.substr(0, i), s2.substr(s2.size() - i))
               && isScramble(s1.substr(i), s2.substr(0, s2.size() - i)))
                return true;
        }

        return false;
    }

bool isValid(const string& s) {

        if(s.size() % 3) return false;
        if(s.size() == 0) return true;

        for(int i = 2; i < s.size(); i ++)
            if(s[i - 2] == 'a' && s[i - 1] == 'b' && s[i] == 'c')
                return isValid(s.substr(0, i - 2) + s.substr(i + 1));
        return false;
    }

bool isWinning(int pos) {
  if (pos == 0)
    return false;  // can't move = terminal position

  int moves[3] = { 1, 3, 4 };
  // play optimally: try all against his optimality
  for (int i = 0; i < 3; ++i) {
    if (pos >= moves[i] && !isWinning(pos - moves[i]))
      // opponent will lose from this move
      return true;  // ANY lose = I win
  }
  return false;  // ALL moves make opponent win
}

