bool ok(const string& s, int start, long long t){

        if(start >= s.size()) return true;

        long long cur = 0ll;
        int i = start;
        for(; i < s.size(); i ++){
            cur = cur * 10ll + (s[i] - '0');
            if(cur > t) return false;
            if(cur == t && ok(s, i + 1, t - 1ll)) return true;
        }
        return false;
    }

bool ok(int num, bool flag){
        if(num == 0)
            return flag;

        int d = num % 10;
        if(d == 3 || d == 4 || d == 7)
            return false;

        if(d == 0 || d == 1 || d == 8)
            return ok(num / 10, flag);

        return ok(num / 10, true);
    }

bool querySegmentTree(int i, int l, int r, vector<int>& segmentTree, int val) {
        if (segmentTree[i] < val)
            return false; // No basket in this segment

        if (l == r) {
            segmentTree[i] = -1; // Mark basket as used
            return true;
        }

        int mid = (l + r) / 2;
        bool placed = false;

        if (segmentTree[2*i + 1] >= val) {
            placed = querySegmentTree(2*i + 1, l, mid, segmentTree, val);
        } else {
            placed = querySegmentTree(2*i + 2, mid + 1, r, segmentTree, val);
        }

        segmentTree[i] = max(segmentTree[2*i + 1], segmentTree[2*i + 2]);

        return placed;
    }

bool recursion(int n, set<int> &s)
  {
    if (n == 0)
      return false;
    if (n == 1)
      return true;
    if (s.find(n) != s.end())
      return false;

    s.insert(n);
    int newNum = 0;
    while (n)
    {
      int digit = n % 10;
      n = n / 10;
      newNum += digit * digit;
    }

    return recursion(newNum, s);
  }

bool subsetSum(int arr[], int n, int sum)
{
    // return true if sum becomes 0 (subset found)
    if (sum == 0)
        return true;

    // base case: no items left or sum becomes negative
    if (n < 0 || sum < 0)
        return false;

    // Case 1. include current item in the subset (arr[n]) and recurse
    // for remaining items (n - 1) with remaining sum (sum - arr[n])
    bool include = subsetSum(arr, n - 1, sum - arr[n]);

    // Case 2. exclude current item n from subset and recurse for
    // remaining items (n - 1)
    bool exclude = subsetSum(arr, n - 1, sum);

    // return true if we get subset by including or excluding current item
    return include || exclude;
}

bool sumOfNumberAndReverse(int num) {
        const function<int(int, int)> backtracking = [&](int num, int chosen) {
            if (num == 0) {
                return true;
            }
            if (chosen == 1) {
                return false;
            }
            if (num <= 18) {
                return (num % 2 == 0) || (num == 11 && chosen == 0);
            }
            if (chosen == 2) {
                return false;
            }
            for (const auto& x : {num % 10, 10 + num % 10}) {
                if (!(1 <= x && x <= 18)) {
                    continue;
                }
                int base = 11;
                if (chosen) {
                    base = chosen;
                } else {
                    for (; x * ((base - 1) * 10 + 1) <= num; base = (base - 1) * 10 + 1);
                }
                if (num - x * base >= 0 && backtracking((num - x * base) / 10, base / 100 + 1)) {
                    return true;
                }
            }
            return false;
        };

        return backtracking(num, 0);
    }

char findKthBit(int n, int k) {

        if(n == 1) {
            return '0';
        }

        int length = (1 << n) - 1; //pow(2, n) - 1

        if(k < ceil(length/2.0)) {
            return findKthBit(n-1, k);
        } else if(k == ceil(length/2.0)) {
            return '1';
        } else {
            char ch = findKthBit(n-1, length-(k-1)); //handled reversed
            return (ch == '0') ? '1' : '0'; //handled flipped bit
        }

    }

char kthCharacter(long long k, vector<int>& operations) {
        // Base case: If k is 1, the result is the initial character 'a'
        if (k == 1) {
            return 'a';
        }

        int n = operations.size();  // Size of the operations array
        int opType;                 // Store the operation type (0 or 1)
        long long len = 1;          // Start with length 1 (initial 'a')
        long long newK;             // To store the adjusted k value

        // Traverse through the operations array to determine the operation type
        for (int i = 0; i < n; i++) {
            len *= 2;               // Double the length at each step
            if (len >= k) {         // If the current length surpasses or equals k
                opType = operations[i];  // Get the current operation type
                newK = k - len / 2;      // Adjust k for the next recursive call
                break;                   // Break as we have found the required operation
            }
        }

        // Recursively find the character before the operation is applied
        char res = kthCharacter(newK, operations);

        // If operation type is 0, return the character as is
        if (opType == 0)
            return res;

        // If operation type is 1, transform the character ('a' becomes 'b', etc.)
        if (res == 'z')
            return 'a';  // Handle wrap-around from 'z' to 'a'

        return res + 1;   // Increment character by 1
    }

double Sqrt(double a) {
    if (a > 0 && a < 1) {
        return 1 / Sqrt(1 / a);
    }
    double l = 0, r = a;
    /* Epsilon is the precision.
    A great precision is
    between 1e-7 and 1e-12.
    double epsilon = 1e-12;
    */
    double epsilon = 1e-12;
    while (l <= r) {
        double mid = (l + r) / 2;
        if (mid * mid > a) {
            r = mid;
        } else {
            if (a - mid * mid < epsilon) {
                return mid;
            }
            l = mid;
        }
    }
    return -1;
}

double arr_average(double arr[], int len) {
    if (len == 1)
        return arr[0];

    double sub_result = arr_average(arr, len - 1);
    // Now this was average of len-1. So sum / (len-1)
    sub_result = sub_result * (len-1);

    return (sub_result + arr[len - 1] ) / len;
}

double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        if(nums1.size() > nums2.size())
            return findMedianSortedArrays(nums2, nums1);

        int m = nums1.size();
        int n = nums2.size();

        int low = 0, high = m;
        while(low <= high) {

            int Px = low + (high-low)/2;
            int Py = (m+n+1)/2 - Px;

            int x1  = (Px == 0) ? INT_MIN : nums1[Px-1];
            int x3 = (Px == m) ? INT_MAX : nums1[Px];

            int x2  = (Py == 0) ? INT_MIN : nums2[Py-1];
            int x4 = (Py == n) ? INT_MAX : nums2[Py];

            if(x1 <= x4 && x2 <= x3) {
                if((m+n)%2 == 0)
                    return (max(x1, x2) + min(x3, x4))/2.0;

                return max(x1, x2);
            } else if(x1 > x4) {
                high = Px-1;
            } else {
                low = Px+1;
            }
        }

        return -1;
    }

double myPow(double x, int n) {

        if(n == 0) return 1.0;

        double t = myPow(x, n / 2);
        if(n % 2 == 0)
            return t * t;
        else if( n > 0)
            return t * t * x;
        return t * t / x;
    }

double power(double x, int n)
{
    if (n == 0)
        return 1.00;
    if (n == 1)
        return x;
    double ans = power(x, n / 2);
    if (n % 2 == 0)
        return ans * ans;
    else if (n < 0)
        return ans * ans / x;
    else
        return ans * ans * x;
}

double solve(double x, long n) {

        if(n == 0)
            return 1;

        if(n < 0)
            return 1/solve(x, -n);


        if(n%2 == 0) {
            return solve(x*x, n/2);
        }

        return x*solve(x*x, (n-1)/2);

    }

