int dfs(int n, const vector<int>& sum, int start, vector<int>& dp){

        if(start >= n - 1) return 0;
        if(start == n - 2) return sum[start + 1];
        if(dp[start] != INT_MIN) return dp[start];

        int res = max(sum[start + 1] - dfs(n, sum, start + 1, dp), dfs(n, sum, start + 1, dp));
        return dp[start] = res;
    }

int dfs(int n, int cur, const vector<int>& cost, int& res){

        if(2 * cur + 1 >= n) return cost[cur];

        int l = dfs(n, 2 * cur + 1, cost, res);
        int r = dfs(n, 2 * cur + 2, cost, res);
        res += abs(l - r);
        return max(l, r) + cost[cur];
    }

int dfs(int n, int index, vector<bool>& used){

        if(index == n + 1) return 1;

        int res = 0;
        for(int num = 1; num <= n; num ++)
            if(!used[num] && (num % index == 0 || index % num == 0)){
                used[num] = true;
                res += dfs(n, index + 1, used);
                used[num] = false;
            }
        return res;
    }

int dfs(int n, int index, vector<int>& row,
            vector<bool>& col, vector<bool>& dia1, vector<bool>& dia2){

        if(index == n)
            return 1;

        int res = 0;
        for(int i = 0; i < n; i ++)
            if(!col[i] && !dia1[index + i] && !dia2[index - i + n - 1]){
                row.push_back(i);
                col[i] = true;
                dia1[index + i] = true;
                dia2[index - i + n - 1] = true;

                res += dfs(n, index + 1, row, col, dia1, dia2);

                col[i] = false;
                dia1[index + i] = false;
                dia2[index - i + n - 1] = false;
                row.pop_back();
            }
        return res;
    }

int dfs(string &s, int i, int prev, int memo[100001][2])
    {
        if (i == s.size())
            return 0;

        if (memo[i][prev] != -1)
            return memo[i][prev];

        int ans = INT_MAX;

        if (prev == 0)
        {
            ans = min(ans, (s[i] == '1' ? 1 : 0) + dfs(s, i + 1, 0, memo));
            ans = min(ans, (s[i] == '1' ? 0 : 1) + dfs(s, i + 1, 1, memo));
        }
        else
        {
            ans = min(ans, (s[i] == '1' ? 0 : 1) + dfs(s, i + 1, 1, memo));
        }

        return memo[i][prev] = ans;
    }

int dfs(string &s, int i, vector<int> &memo)
    {
        if (s.size() == i)
            return 1;

        if (s[i] == '0')
            return 0;

        if (memo[i] != -1)
            return memo[i];

        int ans = 0;
        ans += dfs(s, i + 1, memo);

        if (i + 1 < s.size())
        {
            if (s[i] == '1' || (s[i] == '2' && s[i + 1] <= '6'))
            {
                ans += dfs(s, i + 2, memo);
            }
        }

        return memo[i] = ans;
    }

int dfs(string& s, int l, int r){

        if(l >= r) return 0;
        if(s[l] == s[r]) return dfs(s, l + 1, r - 1);

        int front_pos, tail_pos, front_swaps = 0, tail_swaps = 0;
        for(front_pos = l; front_pos <= r && s[front_pos] != s[r]; front_pos ++, front_swaps ++);
        for(tail_pos = r; tail_pos >= l && s[tail_pos] != s[l]; tail_pos --, tail_swaps ++);


        if(front_swaps <= tail_swaps){
            for(int i = front_pos - 1; i >= l; i --) swap(s[i], s[i + 1]);
            return front_swaps + dfs(s, l + 1, r - 1);
        }

        for(int i = tail_pos + 1; i <= r; i ++) swap(s[i - 1], s[i]);
        return tail_swaps + dfs(s, l + 1, r - 1);
    }

int dfs(vector<int>& pos, int index, vector<int>& neg){

        if(index == pos.size()) return 0;

        int res = INT_MAX;
        for(int& e: neg){
            if(e){
                int t = min(pos[index], e);
                pos[index] -= t;
                e -= t;
                res = min(res, 1 + dfs(pos, index + (pos[index] == 0), neg));
                pos[index] += t;
                e += t;
            }
        }
        return res;
    }

int dfs(vector<string>& A, int i, vector<int>& masks, int mask) {
        if(i == A.size()) return 0;

        int ans = dfs(A, i+1, masks, mask);

        if((mask & masks[i]) == 0) {
            mask = mask | masks[i];
            ans = max(ans, (int)A[i].size() + dfs(A, i+1, masks, mask));
        }

        return ans;
    }

int divideConquer(vector<int>& nums, int l, int r) {
        if(l > r) {
            return INT_MIN;
        }

        int mid   = l + (r-l)/2;
        int Lsum  = divideConquer(nums, l, mid-1);
        int Rsum  = divideConquer(nums, mid+1, r);

        int leftSum  = 0;
        int rightSum = 0;
        int tempSum  =  0 ;
        for(int i = mid-1; i >= l; i--) {
            tempSum += nums[i];
            leftSum = max(leftSum, tempSum);
        }

        tempSum = 0;
        for(int i = mid+1; i <= r; i++) {
            tempSum += nums[i];
            rightSum = max(rightSum, tempSum);
        }

        return max({Lsum, Rsum, leftSum + rightSum + nums[mid]});
    }

