int maxFreeTime(int eventTime, vector<int>& startTime, vector<int>& endTime) {
        const auto& topk = [&](int k) {  // Time: O(k * n)
            vector<pair<int, int>> topk(k, pair(numeric_limits<int>::min(), numeric_limits<int>::min()));
            for (int i = 0; i < size(startTime); ++i) {
                auto x = pair(startTime[i] - endTime[i], endTime[i]);
                for (auto& y : topk) {
                    if (x > y) {
                        swap(x, y);
                    }
                }
            }
            return topk;
        };

        startTime.emplace_back(eventTime);
        endTime.emplace(begin(endTime), 0);
        const auto& top3 = topk(3);
        int result = 0;
        for (int i = 0, curr = 0; i + 1 < size(startTime); ++i) {
            int l = 0;
            for (const auto& [mx, e] : top3) {
                if (e != endTime[i] && e != endTime[i+1] && endTime[i + 1] - startTime[i] <= mx) {
                    l = endTime[i+1] - startTime[i];
                    break;
                }
            }
            result = max(result, (startTime[i] - endTime[i]) + (startTime[i + 1] - endTime[i + 1]) + l);
        }
        return result;
    }

int maxUncrossedLines(vector<int>& A, vector<int>& B) {
        if (A.size() < B.size()) {
            return maxUncrossedLines(B, A);
        }
        vector<vector<int>> dp(2, vector<int>(B.size() + 1));
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < B.size(); ++j) {
                dp[(i + 1) % 2][j + 1] = max(dp[i % 2][j] + static_cast<int>(A[i] == B[j]),
                                             max(dp[i % 2][j + 1], dp[(i + 1) % 2][j]));
            }
        }
        return dp[(A.size()) % 2][B.size()];
    }

int median_of_medians(const std::vector<int>& A,  const int& idx) {
    int pivot = 0;                    // initialized with zero
    std::vector<int> a(A.begin(), A.end());
    std::vector<int> m;
    int r = a.size();
    for(int i = 0; i < r; i += 5){
        std::sort(a.begin() + i, a.begin() + std::min(r, i + 5));
        int mid = (i + std::min(r, i + 5)) / 2;
        m.push_back(a[mid]);
    }
    int sz = int(m.size());
    if(sz <= 5){
        std::sort(m.begin(), m.end());
        pivot = m[(sz- 1) / 2];
    }
    else{
        pivot = median_of_medians(m, idx);
    }
    std::vector<int> low;
    std::vector<int> high;
    for(int i = 0; i < r; i++){
        if(a[i] < pivot){
            low.push_back(a[i]);
        }
        else if(a[i] > pivot){
            high.push_back(a[i]);
        }
    }
    int k = int(low.size());
    if(idx < k){
        return median_of_medians(low, idx);
    }
    else if(idx > k){
        return median_of_medians(high, idx-k-1);
    }
    else{
        return pivot;
    }
}

