int packRecursive(int n, int W, int *w, int *v) {
    // 结束条件（初始条件），i或者j为0时最大总价值为0
    if (n == 0 || W == 0) {
        return 0;
    }
    // 第i个物品不能装下，则递归装i-1个
    if (w[n] > W) {
        return packRecursive(n - 1, W, w, v);
    }
    //第i个物品能装下，则比较包括第i个物品和不包括第i个物品，取其最大值
    else {
        return max(v[n] + packRecursive(n - 1, W - w[n], w, v), packRecursive(n - 1, W, w, v));
    }
}

int playRec(int n)
{
    if(n <= 1)    return 1;

    int cnt = 0;
    for(int i = 0 ; i < n; i+=2)
        for(int j = 2*i; i < n-1; ++i)
            for(int k = (i+j)/2; k < n; k++)
                cnt++;

    int a = playRec(n/2 - 0);
    int b = playRec(n/2 - 1);
    int c = playRec(n/2 - 2);

    return cnt + a + b + c;
}

