}

ll power(ll x, ll n) {
  ll ans = 1;
  for (; n; n >>= 1, x = mul(x, x)) {
    if (n & 1) ans = mul(ans, x);
  }
  return ans;
}

ll sumPows(ll a, int k) { // Return a^1+a^1+a^2+.....a^k    in O(k)
    if (k == 0)
        return 0;

    if (k % 2 == 1)
        return a * (1 + sumPows(a, k - 1));

    ll half = sumPows(a, k / 2);
    return half * (1 + half - sumPows(a, k / 2 -1) );
}

long long Gcd(long long x, long long y) {
  if (x > y) {
    return Gcd(y, x);
  } else if (x == 0) {
    return y;
  } else if (!(x & 1) && !(y & 1)) {  // x and y are even.
    return Gcd(x >> 1, y >> 1) << 1;
  } else if (!(x & 1) && y & 1) {  // x is even, and y is odd.
    return Gcd(x >> 1, y);
  } else if (x & 1 && !(y & 1)) {  // x is odd, and y is even.
    return Gcd(x, y >> 1);
  }
  return Gcd(x, y - x);  // Both x and y are odd.
}

long long _mergeSort(long long arr[], long long temp[], int left, int right)
{
  long long mid, inv_count = 0;
  if (right > left)
  {
    mid = (right + left) / 2;

    inv_count += _mergeSort(arr, temp, left, mid);
    inv_count += _mergeSort(arr, temp, mid + 1, right);
    inv_count += merge(arr, temp, left, mid + 1, right);
  }
  return inv_count;
}

long long count_inversions(int *a, int n) {
    if (n <= 1) {
        return 0;
    }
    int sz1 = n / 2, sz2 = n - sz1;

    // get count of inversions in left and right half
    long long res = count_inversions(a, sz1) + count_inversions(a + sz1, sz2);

    // merge both halves (now copied into t1, resp. t2) into a
    vector<int> t1(a, a + sz1), t2(a + sz1, a + n);
    int k = 0, i = 0, j = 0;
    while (i < sz1 && j < sz2) {
        if (t1[i] <= t2[j]) {
            a[k++] = t1[i++];

            // all elements in t2[0..j-1] (which are j elements) are smaller than t1[i]
            // and are to the right of t1[i] in the original array --> form an inversion
            res += j;
        } else {
            a[k++] = t2[j++];
        }
    }
    while (i < sz1) {
        a[k++] = t1[i++];
        res += j; // j == sz2 holds here
    }
    while (j < sz2) {
        a[k++] = t2[j++];
    }
    return res;
}

