    for(int i=0;i<N;i ++) {
        if(str[i]== prev) {
            cnt++;
        }
        else {
            if(prev=='1'&&cnt>=Q) {
                return false ;
            }
            if(prev=='0'&&cnt>=P) {
                return false ;
            }
            cnt=1 ;
        }
        prev=str[i];
    }
    if(prev=='1'&&cnt>=Q) {
        return false ;
    }
    if(prev=='0'&&cnt>=P) {
        return false ;
    }
    return true ;
}
