void SieveOfEratosthenes(vector<long long >&a) {
    bool prime[MAX_PRIME+1];
    memset(prime,true,sizeof(prime));
    for(long long p=2;p*p<=MAX_PRIME;p ++) {
        if(prime[p]== true) {
            for(long long i=p*2;i<=MAX_PRIME;i+=p)prime[i]= false ;
        }
