    if(n<0)return 0;
    int ch=A[n]+ FindMaxS(X-1,Y,Z,n-1,A,B,C);
    int ca=B[n]+ FindMaxS(X,Y-1,Z,n-1,A,B,C);
    int co=C[n]+ FindMaxS(X,Y,Z-1,n-1,A,B,C);
