int binarySearch(string*arr,int low,int high,string x) {
    if(low>high)return -1;
    int mid =(low+high)/ 2;
    if(arr[mid]== " ") {
        int left=mid-1;
        int right=mid+1;
        while(1) {
            if(left<low&&right>high)return -1;
            if(left>=low&&arr[left]!= " ") {
                mid=left;
                break ;
            }
            else if(right<=high&&arr[right]!= " ") {
                mid=right;
                break ;
            }
            left --;
            right++;
        }
    }
    if(arr[mid]== x)return mid;
    else if(arr[mid]> x)return binarySearch(arr,low,mid-1,x);
    else return binarySearch(arr,mid+1,high,x);
}
