    if(first>last)return -1;
    int mid =(last+first)/ 2;
    if(arr[mid ].empty()) {
        int left=mid-1;
        int right=mid+1;
        while(true) {
            if(left<first&&right>last)return -1;
            if(right<=last&&! arr[right ].empty()) {
                mid=right;
                break ;
            }
            if(left>=first&&! arr[left ].empty()) {
                mid=left;
                break ;
            }
            right ++;
            left--;
        }
    }
    if(compareStrings(str,arr[mid])==0)return mid;
    if(compareStrings(str,arr[mid])<0)return searchStr(arr,str,mid+1,last);
    return searchStr(arr,str,first,mid-1);
