    else if(temp<=q.front()) {
        q.push(temp);
        FrontToLast(q,qsize);
    }
    else {
        q.push(q.front());
        q.pop();
        pushInQueue(q,temp,qsize-1);
    }
}
void sortQueue(queue<int >&q) {
    if(q.empty())return;
    int temp=q.front();
    q.pop();
    sortQueue(q);
    pushInQueue(q,temp,q.size());
}

