int partition(char arr[],int low,int high,int mod) {
    char pivot=arr[high];
    int i =(low-1);
    int piv=pivot%mod;
    for(int j=low;j<=high-1;j ++) {
        int a=arr[j]% mod;
        if(a<=piv) {
            i ++;
            swap(& arr[i],&arr[j]) ;
        }
    }
    swap(& arr[i+1],&arr[high]);
    return(i+1);
}
