vector<int> beautifulArray(int N) {

        if(N == 0) return {};
        if(N == 1) return {1};
        if(N == 2) return {1, 2};

        vector<int> res;
        int odd = (N + 1) / 2, even = N - odd;

        vector<int> left = beautifulArray(odd);
        for(int e: left)
            res.push_back(2 * e - 1);

