vector<string> validStrings(int n) {
        vector<string> result;
        string curr;
        const function<void (int)> backtracking = [&](int i) {
            if (i == n) {
                result.push_back(curr);
                return;
            }
            if (empty(curr) || curr.back() == '1') {
                curr.push_back('0');
                backtracking(i + 1);
                curr.pop_back();
            }
            curr.push_back('1');
            backtracking(i + 1);
            curr.pop_back();
        };

        backtracking(0);
        return result;
    }

vector<vector<int>> permute(int n) {
        vector<vector<int>> result;
        vector<int> curr; curr.reserve(n);
        const function<void (int)> backtracking = [&](int lookup) {
            if (size(curr) == n) {
                result.emplace_back(curr);
                return;
            }
            for (int i = 1; i <= n; ++i) {
                if ((lookup & (1 << (i - 1))) || (!empty(curr) && curr.back() % 2 == i % 2)) {
                    continue;
                }
                curr.emplace_back(i);
                backtracking(lookup ^ (1 << (i - 1)));
                curr.pop_back();
            }
        };

        backtracking(0);
        return result;
    }

