             set<int>& set){

        if(low <= num && num <= high) set.insert(num);

        if(index < len){
            int last = num % 10;
            if(last - 1 >= 0) dfs(len, index + 1, num * 10ll + (last - 1ll), low, high, set);
            if(last + 1 <= 9) dfs(len, index + 1, num * 10ll + (last + 1ll), low, high, set);
        }
    }

