void dfs(vector<int>& edges, int startNode, vector<int>& dist_node, vector<bool>& visited) {
        visited[startNode] = true;

        int v = edges[startNode];

        if(v != -1 && !visited[v]) {
            visited[v] = true;
            dist_node[v] = 1 + dist_node[startNode];
            dfs(edges, v, dist_node, visited);
        }
    }

void dfs(vector<int>& freq, int index, string& cur, vector<string>& res){

        if(index >= cur.size() / 2){
            res.push_back(cur);
            return;
        }

        for(char ch = 0; ch < freq.size(); ch ++)
            if(freq[ch]){
                cur[index] = cur[cur.size() - index - 1] = ch;
                freq[ch] -= 2;
                dfs(freq, index + 1, cur, res);
                freq[ch] += 2;
            }
    }

void findmax(string str, string &ans, int k, int n, int i)
{
  if (k == 0)
    return;

  char maxs = str[i];

  for (int j = i + 1; j < n; j++)
  {
    maxs = max(maxs, str[j]);
  }

  if (maxs != str[i])
    k--;
  for (int j = i; j < n; j++)
  {
    if (str[j] == maxs)
    {
      swap(str[i], str[j]);
      ans = max(ans, str);
      findmax(str, ans, k, n, i + 1);
      swap(str[i], str[j]);
    }
  }
  return;
}

void generate(int idx, vector<int>& nums, vector<int>& result, vector<int>& temp, int prev) {
        if(idx >= nums.size()) {
            if(temp.size() > result.size()) {
                result = temp;
            }
            return;
        }

        if(prev == -1 || nums[idx] % prev == 0) {
            temp.push_back(nums[idx]);
            generate(idx+1, nums, result, temp, nums[idx]);
            temp.pop_back();
        }

        generate(idx+1, nums, result, temp, prev);
    }

void generate(int left, int right, const string& cur, vector<string>& res){

        if(left == 0 && right == 0){
            res.push_back(cur);
            return;
        }

        if(left)
            generate(left - 1, right, cur + '(', res);

        if(right && left < right)
            generate(left, right - 1, cur + ')', res);
    }

