void recurse(string s, int curr, vector<string> &ans)
  {
    if (curr == s.size())
    {
      ans.push_back(s);
      return;
    }

    if (isalpha(s[curr]))
    {
      string n1 = s, n2 = s;
      n1[curr] = toupper(n1[curr]);
      n2[curr] = tolower(n2[curr]);
      recurse(n2, curr + 1, ans);
      recurse(n1, curr + 1, ans);
    }
    else
    {
      recurse(s, curr + 1, ans);
    }
  }

void solve(int curr, int n, vector<int>& result) {
        if(curr > n)
            return;

        result.push_back(curr);

        for(int nextDigit = 0; nextDigit <= 9; nextDigit++) {
            int nextnum = curr*10 + nextDigit;

            if(nextnum > n)
                return;

            solve(nextnum, n, result);
        }
    }

void solve(int n, string &curr, int &count, int k, string &result) {
        if (curr.length() == n) {
            count++;
            if (count == k) {
                result = curr;  // Store only the k-th string
            }
            return;
        }

        for (char ch = 'a'; ch <= 'c'; ch++) {
            if (!curr.empty() && curr.back() == ch)
                continue;

            // Do
            curr.push_back(ch);

            // Explore
            solve(n, curr, count, k, result);

            // If result is found, exit early
            if (!result.empty()) return;

            // Undo
            curr.pop_back();
        }
    }

void solve(int n, string &curr, vector<string> &result) {
        if (curr.length() == n) {
            result.push_back(curr);
            return;
        }

        for (char ch = 'a'; ch <= 'c'; ch++) {
            if (!curr.empty() && curr.back() == ch)
                continue;

            // Do
            curr.push_back(ch);

            // Explore
            solve(n, curr, result);

            // Undo
            curr.pop_back();
        }
    }

void updateSegmentTree(int i, int l, int r, int updateIndex, vector<long long>& segmentTree) {
        if (l == r) {
            segmentTree[i] = 1;
            return;
        }

        int mid = l + (r - l) / 2;
        if (updateIndex <= mid) {
            updateSegmentTree(2 * i + 1, l, mid, updateIndex, segmentTree);
        } else {
            updateSegmentTree(2 * i + 2, mid + 1, r, updateIndex, segmentTree);
        }

        segmentTree[i] = segmentTree[2 * i + 1] + segmentTree[2 * i + 2];
    }
